// keep in sync with n8n/workflows/replenishment-nudge.mjs
const REPLENISHMENT_ALLOWLIST = ['partner_id'];
function assertReplenishmentTrigger(payload) {
  if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
  for (const key of Object.keys(payload)) {
    if (!REPLENISHMENT_ALLOWLIST.includes(key)) throw new Error('unknown replenishment key forbidden: ' + key);
    if (payload[key] != null && typeof payload[key] === 'object') throw new Error('nested objects forbidden');
  }
  if ('partner_id' in payload && payload.partner_id !== false && (typeof payload.partner_id !== 'number' || !Number.isInteger(payload.partner_id) || payload.partner_id < 1)) {
    throw new Error('partner_id must be a positive integer or omitted');
  }
}
const input = $input.first().json;
const headers = input.headers ?? {};
const provided = headers['x-sattva-webhook-hmac'] ?? headers['X-Sattva-Webhook-Hmac'];
const expected = $env.N8N_WEBHOOK_HMAC;
if (typeof expected !== 'string' || !expected || typeof provided !== 'string' || provided !== expected) {
  throw new Error('invalid x-sattva-webhook-hmac');
}
const payload = input.body ?? input;
assertReplenishmentTrigger(payload);
return [{ json: { partner_id: payload.partner_id ?? false } }];
